    taddr = strtonum(t)
    best = ""
    bestaddr = 0
    for (i = 1; i <= count; i++) {
      if (addrs[i] <= taddr && addrs[i] > bestaddr) {
        bestaddr = addrs[i]
        best = funcs[i]
      }
