arguments.command:
DBG="/tmp/sv-f2ca8965935d4d2691ba62d0c696f73d/symbols/libmonosgen-2.0.so.dbg"

# Look up what function the second thunked address maps to 
# We need to find the thunk that specifically contains each of our addresses
# Let's look at all CortexA53 thunks to find which ones our addresses fall in
llvm-readelf-18 -s "$DBG" 2>/dev/null | grep 'CortexA53' | awk '{
  addr = strtonum("0x" $2)
  size = strtonum($3)
  name = $8
  if (addr <= 0x2f4b20 && addr + size > 0x2f4b20) printf "0x2f4b20 in %s @ 0x%x size %d -> patches 0x%s\n", name, addr, size, substr(name, 23)
  if (addr <= 0x2f4c84 && addr + size > 0x2f4c84) printf "0x2f4c84 in %s @ 0x%x size %d -> patches 0x%s\n", name, addr, size, substr(name, 23)
}' 

# Also resolve the actual per-address original functions
# The thunks are typically tiny (8-12 bytes). Let me list thunks near our addresses
llvm-readelf-18 -s "$DBG" 2>/dev/null | grep 'CortexA53' | awk '{
  addr = strtonum("0x" $2)
  name = $8
  size = $3
  if (addr >= 0x2f4b00 && addr <= 0x2f4d00) printf "  0x%x size=%s %s\n", addr, size, name
}' | sort

